import { getLanguageService } from '@bigcommerce/checkout/locale';

import { CustomError, setPrototypeOf } from '../common/error';

export default class SessionExpiredError extends CustomError {
    constructor() {
        super({
            name: 'SESSION_EXPIRED',
            message: getLanguageService().translate('payment.session_expired_error'),
            title: getLanguageService().translate('payment.session_expired_error_heading'),
        });

        setPrototypeOf(this, SessionExpiredError.prototype);
    }
}
