import { cloneDeep } from 'lodash';

import request from '../request'
import { CartOrderExtraInfo, ValidateExtraFieldsModulePayload } from '../request/apis';
import { storage } from '../utils'

import { conversionData, decodeExtraFieldsKeys } from './utils'

import './styles.scss'

export const getB3OrderExtras = () => {
  let B3OrderExtras = storage.B3OrderExtras.getValue()

  B3OrderExtras = B3OrderExtras ? JSON.parse(B3OrderExtras) : []

  return B3OrderExtras
}

export const getDefaultB3OrderExtrasVal = () => {
  const B3OrderExtras = getB3OrderExtras()

  if (B3OrderExtras.length) {
    const customFields: any = {}

    B3OrderExtras.forEach((item: any) => {
      customFields[item.name] = item?.val || ''
    })

    return customFields
  }

  return ''
}

export const getB3OrderFiles = (list: any) => {
  if (list && list.length) {
    const orderConversion = conversionData(list, true);

    const orderFields = cloneDeep(orderConversion);

    storage.B3OrderExtras.setValue(JSON.stringify(orderFields));
  }
}


export const saveOrderExtraVlaues = (values: any) => {
  const orderExtras = getB3OrderExtras()

  if (orderExtras.length > 0) {
    let getOrderVal: any = {}

    orderExtras.map((item: any) => {
      if (!item.visibleToEnduser) {
        getOrderVal[item.name] = ''
      }
    })

    if ((values )?.customFields) {
      getOrderVal = { ...(values )?.customFields, ...getOrderVal }
    }

    localStorage.setItem('B3PaymentCustomFields', JSON.stringify(getOrderVal))
  }
}

export const validateOrderExtraFields = async (values: any) => {
  const payload: ValidateExtraFieldsModulePayload = {
    extraFields: [],
  }

  if ((values )?.customFields && JSON.stringify((values )?.customFields) !== '{}') {
    const { customFields }: any = values
    const decodeExtraField = decodeExtraFieldsKeys(customFields)
    const extraFields = Object.keys(decodeExtraField).map((item: any) => {
      return {
        fieldName: item,
        fieldValue: decodeExtraField[item]
      }
    })

    payload.extraFields = extraFields 
  }
  
  const poNumber = storage.B3PoNumber.getValue() || ''

  if (poNumber.length > 0) {
    payload.poNumber = poNumber
  }

  const referenceNumber = storage.B3PaymentsAdditionalTextFieldValue.getValue() || ''

  if(referenceNumber.length > 0) {
    payload.referenceNumber = referenceNumber
  }

  if(Object.keys(payload).length === 0) return
  
  const { comments } = await request.api.validateExtraFieldsModule('order', payload)

  return { comments, payload }
}

export const saveCartOrderExtraInfo = async (data: CartOrderExtraInfo) => {
  return await request.api.saveCartOrderExtraInfo(data)
}
