export interface ResolveBackorderBannerMessageInputs {
    showBackorderMessages: boolean;
    warningFlashMessage?: string;
    quoteStockChangeMessage?: string;
}

export default function resolveBackorderBannerMessage({
    showBackorderMessages,
    warningFlashMessage,
    quoteStockChangeMessage,
}: ResolveBackorderBannerMessageInputs): string | undefined {
    if (!showBackorderMessages) {
        return undefined;
    }

    return warningFlashMessage ?? quoteStockChangeMessage;
}
