const CryptoJS = require('crypto-js')
const tripledes = require('crypto-js/tripledes')

const encryptedStr = 'B3Info'

const cipherText = (text: any) => {
  if (!text) return ''

  text = (typeof text === 'boolean' || typeof text === 'number') ? text.toString() : text

  return tripledes.encrypt(text, encryptedStr).toString()
}

const plainText = (text: any) => {
  if (!text) return ''

  const decodedText = tripledes.decrypt(text, encryptedStr).toString(CryptoJS.enc.Utf8)

  if (!decodedText) return text

  return decodedText
}

const setCipherTextToStorage = (key: any, value: any) => {
  sessionStorage.setItem(key, cipherText(value))
}

const getPlainTextFromStorage = (key: any) => plainText(sessionStorage.getItem(key))

export default {
  cipherText,
  plainText,
  setCipherTextToStorage,
  getPlainTextFromStorage,
}
