import { Region, Country, CheckoutStoreSelector } from '@bigcommerce/checkout-sdk'
import request from '../request'
import store from '../store'
import { setDefaultBillingAddress, setDefaultShippingAddress, setAddresses, setCountries, B3CustomerAddress } from '../store/actions'
import { storage, util } from '../utils'
import { addNewB3Address } from './addNewB3Address'
import Base64 from '../utils/base64'

const setCompanyCountries = async () => {
  const { list } = await request.api.getCountries()

  const formatCountries = list.map(({
    countryCode,
    countryName,
    states,
  }) => {
    const subdivisions = states.map(({
      stateCode,
      stateName,
    }) => ({
      code: stateCode,
      name: stateName
    }) as Region)
    return {
      code: countryCode,
      name: countryName,
      hasPostalCodes: true,
      requiresState: true,
      subdivisions,
    } as Country
  })

  store.dispatch(setCountries(formatCountries))
}

