const setCompanyDefaultAddress = async (data: CheckoutStoreSelector, selectCompanyHierarchyId: number) => {
  const companyId = storage.B3CompanyId.getValue()
  const { company } = store.getState()

  const {
    defaultBillingId,
    defaultShippingId,
    addresses: b2bAddresses,
  } = await request.api.getAddressesAll(selectCompanyHierarchyId || companyId)

  // extraFields fieldName is cipherText
  const addresses: any = {}
  Object.keys(b2bAddresses).forEach((item: any) => {
    addresses[item] = b2bAddresses[item]
    const addressExtraFields = b2bAddresses[item]?.extraFields || []
    if (addressExtraFields?.length) {
      const newAddressExtraFields = addressExtraFields.map((address: any) => {
        const extraFieldsItem: any = {}
        extraFieldsItem.fieldName = Base64.encode(address.fieldName)
        extraFieldsItem.fieldValue = address.fieldValue
        return extraFieldsItem
      })

      addresses[item] = b2bAddresses[item]
      addresses[item].extraFields = newAddressExtraFields
    }
  })
  const formatAddress = util.formatAddresses(company.companyBasicInfo.companyName, addresses, data)

  const defaultShippingAddress = defaultShippingId ? formatAddress.find(address => address.id === +defaultShippingId) : {}
  const defaultBillingAddress = defaultBillingId ? formatAddress.find(address => address.id === +defaultBillingId) : {}

  defaultShippingId && store.dispatch(setDefaultShippingAddress(defaultShippingAddress as B3CustomerAddress))
  defaultBillingId && store.dispatch(setDefaultBillingAddress(defaultBillingAddress as B3CustomerAddress))


  if (defaultShippingId) storage.selectShoppingAddressId.setValue(defaultShippingId)
  if (defaultBillingId) storage.selectBillAddressId.setValue(defaultBillingId)

  store.dispatch(setAddresses(formatAddress as B3CustomerAddress[]))
}


const init = async (data: CheckoutStoreSelector, selectCompanyHierarchyId: number) => {
  const { global: { isB3User } } = store.getState()

  if (!isB3User || storage.isDisabledB2BCustomAddress.getValue() === '1') return

  // if (!storage.B3AddressBookIsEnabled.getValue()) await setAddressPermission()
  // if (storage.B3AddressBookIsEnabled.getValue() !== constants.B3AddressBookPermission.isEnabled) return

  await setCompanyDefaultAddress(data, selectCompanyHierarchyId)
  setCompanyCountries()
}

const convertAddress = (address: any) => {
  if (!address) return {}
  const newAddress = {
    customFields: address.customFields,
    firstName: address.firstName,
    lastName: address.lastName,
    company: address.company,
    address1: address.address1,
    address2: address.address2,
    city: address.city,
    stateOrProvince: address.stateOrProvince,
    stateOrProvinceCode: address.stateOrProvinceCode,
    countryCode: address.countryCode,
    postalCode: address.postalCode,
    phone: address.phone,
    country: address.country,
    shouldSaveAddress: address.shouldSaveAddress || '',
  }

  return newAddress
}

export default {
  init,
  addNewB3Address,
  convertAddress,
}