import axios from 'axios'

import store from '../store'
import { showGlobalError } from '../store/actions'
import { storage } from '../utils'

import envConfig from './envConfig'
import { mapToCompanyError, COMPANY_STATUS_MESSAGES } from './companyUtils'

interface CustomCheckoutWindow extends Window {
  B2B_ENV?: string
}

const customCheckoutWindow: CustomCheckoutWindow = window as CustomCheckoutWindow

const env: string = customCheckoutWindow?.B2B_ENV === 'staging' ? 'staging' : customCheckoutWindow?.B2B_ENV || 'production'

const b3request = axios.create({
  baseURL: envConfig[env].baseUrl,
  timeout: 1000 * 10 * 60 * 5,
})

b3request.interceptors.request.use(config => {
  const bcToken = store.getState().global.bcToken
  config.headers = {
    ...config.headers,
    authToken: storage.B3B2BToken.getValue() || bcToken || '', 
    Authorization: `Bearer  ${storage.B3B2BToken.getValue() || ''}`,
  }
  if (config.params && config.params.orderBy) {
    config.params = {
      ...config.params,
    }
  }

  return config
})

b3request.interceptors.response.use(resp => {
  const {
    code,
    message,
    data,
    detail
  } = resp.data

  // if (resp.request)

  const validStatusCodes = [200, 204]

  let responseCode = code;

  if (!validStatusCodes.includes(resp.status)) {
    store.dispatch(showGlobalError(new Error(resp.statusText)))
  }

  if (resp.config.url === "/graphql") {
    return data 
  }

  if (resp.status === 204) {
    responseCode = resp.status
    return {
      code: 200,
      data: {},
      message: 'SUCCESS',
    }
  }

  switch (responseCode) {
    case 200: break
    case 204: break
    case 10015: return Promise.reject()
    case 10020:
      return mapToCompanyError(
        new Error(message || COMPANY_STATUS_MESSAGES.pendingApprovalToOrder),
      );
    default: {
      store.dispatch(showGlobalError(new Error(message || detail)))
      return Promise.reject()
    }
  }

  return data
})

export default b3request
