import { storage }  from '../utils'
import Base64 from '../utils/base64'

export const getB3BillingAddressExtras = () => {
  let B3BillingAddressExtras = storage.B3BillingAddressExtras.getValue()

  B3BillingAddressExtras = B3BillingAddressExtras ? JSON.parse(B3BillingAddressExtras) : []
 
  return B3BillingAddressExtras
}

export const getB3ShippingAddressExtras = () => {
  let B3ShippingAddressExtras = storage.B3ShippingAddressExtras.getValue()

  B3ShippingAddressExtras = B3ShippingAddressExtras ? JSON.parse(B3ShippingAddressExtras) : []
 
  return B3ShippingAddressExtras
}

