export type CompanyStatusKey =
    | 'pendingApprovalToViewPrices'
    | 'pendingApprovalToOrder'
    | 'pendingApprovalToAccessFeatures'
    | 'accountInactive';

interface CompanyStatusMapping {
    message: string;
    reason: CompanyStatusKey;
}

export const COMPANY_STATUS_MESSAGES: Record<CompanyStatusKey, string> = {
    pendingApprovalToViewPrices: 'Your business account is pending approval. You will gain access to business account features, products, and pricing after account approval.',
    pendingApprovalToOrder: 'Your business account is pending approval. Products, pricing, and ordering will be enabled after account approval.',
    pendingApprovalToAccessFeatures: 'Your business account is pending approval. You will gain access to business account features after account approval.',
    accountInactive: 'This business account is inactive. Reach out to our support team to reactivate your account.',
};

export const COMPANY_STATUS_MESSAGE_MAPPINGS: Record<string, CompanyStatusKey> =
    Object.fromEntries(
        (Object.entries(COMPANY_STATUS_MESSAGES) as Array<[CompanyStatusKey, string]>).map(
            ([key, message]) => [message, key],
        ),
    ) as Record<string, CompanyStatusKey>;

export class CompanyError extends Error {
    readonly code = 10020;
    readonly reason: CompanyStatusKey;

    constructor({ message, reason }: CompanyStatusMapping) {
        super(message);
        this.name = 'CompanyError';
        this.reason = reason;
        // Required when targeting ES5: TypeScript doesn't fix the prototype chain
        // for classes extending built-ins (Error, Array, etc.)
        Object.setPrototypeOf(this, CompanyError.prototype);
    }
}

export const mapToCompanyError = (error: unknown): never => {
    if (error instanceof Error) {
        const reason = COMPANY_STATUS_MESSAGE_MAPPINGS[error.message];

        if (reason) {
            throw new CompanyError({ message: error.message, reason });
        }

        throw error;
    }

    const message =
        typeof error === 'object' && error !== null && 'message' in error
            ? String((error as { message: unknown }).message)
            : String(error);

    throw new Error(message);
};


export const isCompanyError = (error: unknown): error is CompanyError => {
    return error instanceof CompanyError;
};

export function mapCompanyErrorReasonToMessage(
    reason: CompanyStatusKey,
    translate: (key: string) => string,
): string {
    switch (reason) {
        case 'pendingApprovalToViewPrices':
            return translate('customer.pending_approval_to_view_prices_error');

        case 'pendingApprovalToOrder':
            return translate('customer.pending_approval_to_order_error');

        case 'pendingApprovalToAccessFeatures':
            return translate('customer.pending_approval_to_access_features_error');

        case 'accountInactive':
            return translate('customer.inactive_company_status_error');

        default:
            return translate('customer.pending_approval_to_order_error');
    }
}
