const SESSION_STORAGE_KEY = 'b2b.quote.backorderChange';

export default function getQuoteStockChangeMessage(
    translate: (key: string) => string,
): string | undefined {
    if (sessionStorage.getItem(SESSION_STORAGE_KEY) !== 'true') {
        return undefined;
    }

    sessionStorage.removeItem(SESSION_STORAGE_KEY);

    return translate('cart.backorder_quantities_changed');
}
