import { Checkout } from '@bigcommerce/checkout-sdk'

import request from '../request'
import store from '../store'
import { setGlobalIsB3User } from '../store/actions'
import { constants, storage, util } from '../utils'

import { errorFn } from './utils'

export const setB3CompanyInfo = async (
  roleId: string,
  customerId: number,
  userId: string
) => {
  let companyId;
  let companyName;
  let companyStatus;

  if (roleId === constants.B3Role.SALESREP) {
    ({ companyId, companyName, companyStatus } = await request.api.getSalesRepMasquerading(customerId));
  } else {
    ({ companyId, companyName, companyStatus } = await request.api.getCompany(userId));
  }

  [
    [companyStatus, storage.B3CompanyStatus],
    [companyId, storage.B3CompanyId],
    [companyName, storage.B3CompanyName]
  ].forEach(([value, store]) => {
    if (value) {
      store.setValue(value);
    }
  });

  return companyId;
}

export const salesRepVerify = async() => {

  const B3CustomerId = storage.B3CustomerId.getValue()
  const B3RoleId = storage.B3RoleId.getValue()

  if (B3RoleId !== constants.B3Role.SALESREP) return true

  const query = B3CustomerId

  try {
    const { companyId } = await request.api.getSalesRepMasquerading(
      query as never
    )

    if (!companyId) {
      await errorFn()

      return false
    }

    return true
  } catch (error) {
    return false
  }
}

export default async (customerId: number, storeHash: string, checkout?: Checkout) => {
  if (!checkout) {
    return;
  }

  const bcToken = await request.bcApi.getBcToken();

  if (!bcToken) {
    return;
  }

  try {
    const { token } = await request.api.getToken({ bcToken, customerId, storeHash, channelId: checkout.channelId });

    // This need to be set first to be used in other B2B API calls
    storage.B3B2BToken.setValue(token);
    sessionStorage.setItem('sf-B3B2BToken', JSON.stringify(token));

    const [{ isEnabled }, { roleId, userId, email }] = await Promise.all([
      request.api.getAllowJuniorPlaceOrders(),
      request.api.getUserRole(customerId),
    ]);

    storage.juniorCheckoutEnabled.setValue(isEnabled);

    storage.B3RoleId.setValue(roleId);
    storage.B3UserId.setValue(userId);
    storage.B3Email.setValue(email);
    storage.B3CustomerId.setValue(customerId);

    const [companyId, userInfo] = await Promise.all([
      setB3CompanyInfo(roleId, customerId, userId),
      +roleId === +constants.B3Role.JUNIOR ? await request.api.getUserInfo() : Promise.resolve(),
    ]);

    if (userInfo?.currentUser.companyRoleId) {
        const {
          companyRole: {
            permissions,
            roleType,
          }
        } = await request.api.getCompanyRole(companyId ? +companyId : 0, +userInfo?.currentUser.companyRoleId);

        storage.juniorCheckoutEnabled.setValue(+roleType === +constants.B3Role.JUNIOR ? '1' : '0');

        const isAddressesPermissions = permissions.find((permissions) => permissions.code === 'get_addresses');

        storage.isDisabledB2BCustomAddress.setValue(isAddressesPermissions ? '0' : '1');
    }
  } finally {
    store.dispatch(setGlobalIsB3User(util.detectB3User()));
  }
}
